38	     * this many owners (excluding the owner itself), approaching the hard capacity limit.
39	     */
40	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
41	
42	    /**
43	     * The hard per-city capacity limit; at or above it a create is rejected rather than warned, so
44	     * the warning window is {@code [CAPACITY_WARNING_THRESHOLD, CITY_CAPACITY)}.
45	     */
