53	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
54	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
55	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
56	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
57	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
58	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
59	    @Mapping(target = "locality", expression = "java(locality(owner))")
60	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
61	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
62	    @Mapping(target = "capacityWarning", expression = "java(capacityWarning(owner))")
63	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
64	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
65	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
66	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
67	    public abstract OwnerDto toOwnerDto(Owner owner);
68	
69	    /**
70	     * The month the fiscal year starts on (1 July).
71	     */
72	    private static final int FISCAL_YEAR_START_MONTH = 7;
73	
74	    /**
75	     * Derives the fiscal year (as an integer) of the given date. The fiscal year starts on 1 July,
76	     * so a date on or after 1 July belongs to the following calendar year's fiscal year (e.g.
77	     * 2026-07-01 is fiscal year 2027) while an earlier date takes the calendar year unchanged.
78	     */
79	    private int fiscalYearOf(LocalDate date) {
80	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
81	    }
82	
83	    /**
84	     * Derives the owner's {@code fiscalYear}, formatted {@code FY<YY>} where YY is the last two
85	     * digits of the fiscal year (starting 1 July) of the owner's business-day-adjusted
86	     * {@code registrationDate}. Returns {@code null} when no registration date is present.
87	     */
88	    protected String fiscalYear(Owner owner) {
89	        LocalDate registrationDate = owner.getRegistrationDate();
90	        if (registrationDate == null) {
91	            return null;
92	        }
93	        return String.format("FY%02d", fiscalYearOf(registrationDate) % 100);
94	    }
95	
96	    /**
97	     * Derives the owner's {@code ageBand} from their {@code birthDate} relative to their
98	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64, and
99	     * {@code SENIOR} at 65 or older. Returns {@code null} when no birth date was supplied, or when
100	     * the registration date (against which the age is measured) is absent.
101	     */
102	    protected OwnerDto.AgeBandEnum ageBand(Owner owner) {
103	        LocalDate birthDate = owner.getBirthDate();
104	        LocalDate registrationDate = owner.getRegistrationDate();
105	        if (birthDate == null || registrationDate == null) {
106	            return null;
107	        }
108	        int age = Period.between(birthDate, registrationDate).getYears();
109	        if (age < 18) {
110	            return OwnerDto.AgeBandEnum.MINOR;
111	        }
112	        if (age < 65) {
113	            return OwnerDto.AgeBandEnum.ADULT;
114	        }
115	        return OwnerDto.AgeBandEnum.SENIOR;
116	    }
117	
118	    /**
119	     * The country calling codes (without the leading {@code '+'}) the display formatter recognises,
120	     * longest first so the correct code is matched before a shorter prefix of it. Australia
121	     * ({@code +61}) and the North American Numbering Plan ({@code +1}) mirror the codes the create
122	     * endpoint normalizes against.
123	     */
124	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
125	
126	    /**
127	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted for
128	     * humans as the country code, a space, then the national digits grouped in threes (e.g.
129	     * {@code +61412345678} becomes {@code +61 412 345 678}). Returns the raw value unchanged when it
130	     * is {@code null} or not an E.164 number ({@code '+'} followed by digits).
131	     */
132	    protected String telephoneDisplay(Owner owner) {
133	        String telephone = owner.getTelephone();
134	        if (telephone == null || !telephone.matches("\\+[0-9]+")) {
135	            return telephone;
136	        }
137	        String digits = telephone.substring(1);
138	        String countryCode = KNOWN_COUNTRY_CODES.stream()
139	            .filter(digits::startsWith)
140	            .findFirst()
141	            .orElse("");
142	        String national = digits.substring(countryCode.length());
143	        StringBuilder grouped = new StringBuilder();
144	        for (int i = 0; i < national.length(); i++) {
145	            if (i > 0 && i % 3 == 0) {
146	                grouped.append(' ');
147	            }
148	            grouped.append(national.charAt(i));
149	        }
150	        return "+" + countryCode + " " + grouped;
151	    }
152	
153	    /**
154	     * Derives the owner's {@code identityKey}, the single consolidated duplicate-detection key: the
155	     * lower-case hex SHA-256 of {@code normalizedTelephone + '|' + lowerEmail + '|' +
156	     * soundex(lastName)}. A {@code null} telephone or email contributes an empty segment.
157	     */
158	    protected String identityKey(Owner owner) {
159	        return IdentityKeys.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
160	    }
161	
162	    /**
163	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
164	     * present, otherwise {@code PHONE}.
165	     */
166	    protected OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
167	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
168	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
169	    }
170	
171	    /**
172	     * The inclusive 4-digit postcode range that identifies each region, keyed by region code
173	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
174	     */
175	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
176	        "NSW", new int[] {2000, 2099},
177	        "VIC", new int[] {3000, 3099},
178	        "QLD", new int[] {4000, 4099});
179	
180	    /**
181	     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
182	     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
183	     * moves in lockstep with the identity assigned on create. When no customer code has been
184	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
185	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
186	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
187	     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
188	     */
189	    protected String locality(Owner owner) {
190	        String customerCode = owner.getCustomerCode();
191	        if (customerCode != null) {
192	            int dash = customerCode.indexOf('-');
193	            if (dash > 0) {
194	                return customerCode.substring(0, dash);
195	            }
196	        }
197	        String fromPostcode = regionFromPostcode(owner.getPostcode());
198	        if (fromPostcode != null) {
199	            return fromPostcode;
200	        }
201	        String city = owner.getCity();
202	        if (city == null) {
203	            return "UNKNOWN";
204	        }
205	        return switch (city) {
206	            case "Sydney" -> "NSW";
207	            case "Melbourne" -> "VIC";
208	            case "Brisbane" -> "QLD";
209	            default -> "UNKNOWN";
210	        };
211	    }
212	
213	    /**
214	     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
215	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
216	     */
217	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
218	        "NSW", "Australia/Sydney",
219	        "VIC", "Australia/Melbourne",
220	        "QLD", "Australia/Brisbane");
221	
222	    /**
223	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
224	     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
225	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
226	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
227	     */
228	    protected String timezone(Owner owner) {
229	        return REGION_TIMEZONE.get(locality(owner));
230	    }
231	
232	    /**
233	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
234	     * the postcode is absent, not 4 digits, or in no known range.
235	     */
236	    private String regionFromPostcode(String postcode) {
237	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
238	            return null;
239	        }
240	        int value = Integer.parseInt(postcode);
241	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
242	            int[] range = entry.getValue();
243	            if (value >= range[0] && value <= range[1]) {
244	                return entry.getKey();
245	            }
246	        }
247	        return null;
248	    }
249	
250	    /**
251	     * The minimum household size (counting the owner itself) that earns household membership
252	     * points.
253	     */
254	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
255	
256	    /**
257	     * An owner's tenure must span strictly more than this many elapsed fiscal years to earn the
258	     * tenure membership points. A newly created owner has zero elapsed fiscal years and so never
259	     * clears this threshold.
260	     */
261	    private static final int TENURE_POINTS_FISCAL_YEARS = 1;
262	
263	    /**
264	     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
265	     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
266	     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
267	     * tenure exceeds {@value #TENURE_POINTS_FISCAL_YEARS} elapsed fiscal year(s).
268	     */
269	    protected Integer membershipPoints(Owner owner) {
270	        int points = 0;
271	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
272	        if (hasEmail) {
273	            points += 2;
274	        }
275	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
276	        if (noNamesakes) {
277	            points += 1;
278	        }
279	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
280	            points += 2;
281	        }
282	        if (tenureFiscalYears(owner) > TENURE_POINTS_FISCAL_YEARS) {
283	            points += 3;
284	        }
285	        return points;
286	    }
287	
288	    /**
289	     * Derives the owner's membership level, capped by their household. The level starts from the
290	     * owner's own {@link #uncappedMembershipLevel(Owner) points-based level} but may not exceed one
291	     * above the current maximum level among the owner's existing household members (other owners
292	     * sharing its {@code householdId}). When the owner has no existing household member no cap
293	     * applies and the points-based level is returned unchanged.
294	     */
295	    protected Integer membershipLevel(Owner owner) {
296	        int level = uncappedMembershipLevel(owner);
297	        OptionalInt maxHouseholdLevel = otherHouseholdMembers(owner)
298	            .mapToInt(this::uncappedMembershipLevel)
299	            .max();
300	        if (maxHouseholdLevel.isEmpty()) {
301	            return level;
302	        }
303	        return Math.min(level, maxHouseholdLevel.getAsInt() + 1);
304	    }
305	
306	    /**
307	     * The owner's points-based membership level, before the household ceiling is applied: level 1
308	     * for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more (see
309	     * {@link #membershipPoints(Owner) membership points}). The household members' maximum against
310	     * which {@link #membershipLevel(Owner)} caps is measured with this uncapped value, so mutual
311	     * household members do not recurse into each other's caps.
312	     */
313	    private int uncappedMembershipLevel(Owner owner) {
314	        int points = membershipPoints(owner);
315	        if (points <= 1) {
316	            return 1;
317	        }
318	        if (points <= 3) {
319	            return 2;
320	        }
321	        if (points <= 5) {
322	            return 3;
323	        }
324	        return 4;
325	    }
326	
327	    /**
328	     * The owner's existing household members: every other owner (excluding the owner itself) sharing
329	     * its {@code householdId}. Empty when the owner has no household identifier or is the sole member
330	     * of its household.
331	     */
332	    private Stream<Owner> otherHouseholdMembers(Owner owner) {
333	        String householdId = owner.getHouseholdId();
334	        if (householdId == null) {
335	            return Stream.empty();
336	        }
337	        return this.clinicService.findAllOwners().stream()
338	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
339	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()));
340	    }
341	
342	    /**
343	     * The number of owners in this owner's household — the count of owners (including this one)
344	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
345	     */
346	    private long householdSize(Owner owner) {
347	        String householdId = owner.getHouseholdId();
348	        if (householdId == null) {
349	            return 0;
350	        }
351	        return this.clinicService.findAllOwners().stream()
352	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
353	            .count();
354	    }
355	
356	    /**
357	     * The owner's tenure in elapsed fiscal years: the number of fiscal years (each starting 1 July)
358	     * between their {@code registrationDate} and the current date, i.e. the current fiscal year less
359	     * the registration date's fiscal year. Returns 0 when no registration date is present, so an
360	     * owner without a registration date is treated as having no tenure.
361	     */
362	    private long tenureFiscalYears(Owner owner) {
363	        LocalDate registrationDate = owner.getRegistrationDate();
364	        if (registrationDate == null) {
365	            return 0;
366	        }
367	        return (long) fiscalYearOf(LocalDate.now()) - fiscalYearOf(registrationDate);
368	    }
369	
370	    /**
371	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
372	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
373	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
374	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
375	     * owner has no registration date.
376	     */
377	    protected Boolean bulkSignupWarning(Owner owner) {
378	        LocalDate registrationDate = owner.getRegistrationDate();
379	        if (registrationDate == null) {
380	            return false;
381	        }
382	        long othersOnDay = this.clinicService.findAllOwners().stream()
383	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
384	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
385	            .count();
386	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
387	    }
388	
389	    /**
390	     * Flags a city approaching its hard capacity limit: {@code true} when this owner's city already
391	     * holds between {@link #CAPACITY_WARNING_THRESHOLD} and {@link #CITY_CAPACITY} minus one owners,
392	     * inclusive (excluding the owner itself), so on a create the flag reflects the owners that
393	     * pre-existed it in that city, matching the count the per-city capacity limit is enforced
394	     * against. Cities are compared case-insensitively, as they are for the capacity limit. Returns
395	     * {@code false} when the owner has no city.
396	     */
397	    protected Boolean capacityWarning(Owner owner) {
398	        String city = owner.getCity();
399	        if (city == null) {
400	            return false;
401	        }
402	        long othersInCity = this.clinicService.findAllOwners().stream()
403	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
404	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
405	            .count();
406	        return othersInCity >= CAPACITY_WARNING_THRESHOLD && othersInCity < CITY_CAPACITY;
407	    }
408	
409	    /**
410	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the digits
411	     * contained in the owner's {@code customerCode}. Non-digit characters are ignored. Returns
412	     * {@code null} when no customer code has been assigned.
413	     */
414	    protected Integer checkDigit(Owner owner) {
415	        String customerCode = owner.getCustomerCode();
416	        if (customerCode == null) {
417	            return null;
418	        }
419	        int sum = 0;
420	        boolean dbl = true;
421	        for (int i = customerCode.length() - 1; i >= 0; i--) {
422	            char c = customerCode.charAt(i);
423	            if (c < '0' || c > '9') {
