441	     * separated by a single space (e.g. {@code DR Franklin}), or just the {@code lastName} when no
442	     * title was supplied (a {@code null} or blank title).
443	     */
444	    protected String salutation(Owner owner) {
445	        String title = owner.getTitle();
446	        String lastName = owner.getLastName();
447	        if (title == null || title.isBlank()) {
448	            return lastName;
449	        }
450	        return title + " " + lastName;
451	    }
